import crypto from "node:crypto";
import { API_VERSION } from "./Api.js";
import getBody from "raw-body";
/**
 * Top.gg Webhook
 *
 * @example
 * ```js
 * import { Webhook } from "@top-gg/sdk";
 * import express from "express";
 *
 * const app = express();
 * const webhook = new Webhook(process.env.TOPGG_WEBHOOK_SECRET);
 *
 * // POST /webhook
 * app.post("/webhook", webhook.listener((payload) => {
 *   console.log(payload);
 * }));
 *
 * app.listen(8080);
 * ```
 *
 * @link {@link https://docs.top.gg/resources/webhooks/#schema | Webhook Data Schema}
 * @link {@link https://docs.top.gg/resources/webhoooks | Webhook Documentation}
 */
export class Webhook {
    secret;
    options;
    /**
     * Create a new webhook client instance
     *
     * @param {string} secret The secret to verify requests
     */
    constructor(secret, options = {}) {
        this.secret = secret;
        this.options = {
            error: options.error ?? console.error,
            timeout: options.timeout ?? 5000,
            timestampWindow: options.timestampWindow ?? 30000,
        };
    }
    _formatPartialProject(project) {
        return {
            id: project.id,
            type: project.type,
            platform: project.platform,
            platformId: project.platform_id,
        };
    }
    _formatUser(user) {
        return {
            id: user.id,
            name: user.name,
            avatar: user.avatar_url,
            platformId: user.platform_id,
        };
    }
    _formatIncoming(body, trace) {
        let data;
        switch (body.type) {
            case "integration.create": {
                data = {
                    connectionId: body.data.connection_id,
                    secret: body.data.webhook_secret,
                    project: this._formatPartialProject(body.data.project),
                    user: this._formatUser(body.data.user),
                };
                this.secret = data.secret;
                break;
            }
            case "integration.delete": {
                data = {
                    connectionId: body.data.connection_id,
                };
                break;
            }
            case "vote.create": {
                data = {
                    id: body.data.id,
                    weight: body.data.weight,
                    votedAt: new Date(body.data.created_at),
                    expiresAt: new Date(body.data.expires_at),
                    project: this._formatPartialProject(body.data.project),
                    query: body.data.query,
                    user: this._formatUser(body.data.user),
                };
                break;
            }
            case "webhook.test": {
                data = {
                    project: this._formatPartialProject(body.data.project),
                    user: this._formatUser(body.data.user),
                };
                break;
            }
            default: {
                throw new Error(`Got an unrecognized payload type '${body.type}'.`);
            }
        }
        return {
            type: body.type,
            data,
            trace,
        };
    }
    _parseRequest(req, res) {
        const currentTimestamp = Date.now();
        return new Promise((resolve) => {
            getBody(req, {
                limit: 2 * 1024 * 1024,
            }, (error, body) => {
                /* node:coverage ignore next 4 */
                if (error) {
                    res.status(400).json({ error: "Malformed request" });
                    return resolve(false);
                }
                let signatureHeader = req.headers["x-topgg-signature"];
                /* node:coverage ignore next 3 */
                if (Array.isArray(signatureHeader)) {
                    signatureHeader = signatureHeader[0];
                }
                if (!signatureHeader) {
                    res.status(401).json({ error: "Missing signature" });
                    return resolve(false);
                }
                const parsedSignature = Object.fromEntries(signatureHeader.split(",").map((part) => part.split("=")));
                const signature = parsedSignature[API_VERSION];
                if (!parsedSignature.t || !signature) {
                    res.status(422).json({ error: "Invalid signature format" });
                    return resolve(false);
                }
                if (this.options.timestampWindow &&
                    Math.abs(currentTimestamp - parseInt(parsedSignature.t, 10) * 1000) > this.options.timestampWindow) {
                    res
                        .status(403)
                        .json({ error: "Timestamp outside of accepted time window" });
                    return resolve(false);
                }
                const hmac = crypto.createHmac("sha256", this.secret);
                const digest = Buffer.from(hmac.update(`${parsedSignature.t}.${body}`).digest("hex"), "hex");
                if (!crypto.timingSafeEqual(Buffer.from(signature, "hex"), digest)) {
                    res.status(403).json({ error: "Invalid signature" });
                    return resolve(false);
                }
                const bodyString = body.toString("utf8");
                try {
                    const parsed = JSON.parse(bodyString);
                    return resolve(this._formatIncoming(parsed, req.headers["x-topgg-trace"]));
                }
                catch (err) {
                    /* node:coverage ignore next 3 */
                    console.warn(`[WARNING] Unable to parse Top.gg webhook payload. Please report this bug to the SDK maintainers.\nCause: ${err.stack || err.message || err}\n--- BEGIN BODY DUMP ---\n${bodyString}\n--- END BODY DUMP ---`);
                    res.sendStatus(204);
                    return resolve(false);
                }
            });
            setTimeout(() => {
                req.destroy();
                res.status(408).json({ error: "Request timed out" });
                resolve(false);
            }, this.options.timeout);
        });
    }
    /**
     * Listening function for handling webhook requests
     *
     * @example
     * ```js
     * // POST /webhook
     * app.post("/webhook", webhook.listener((payload) => {
     *   console.log(payload);
     * }));
     * ```
     *
     * @example
     * ```js
     * // POST /webhook
     * // Throwing an error to resend the webhook
     * app.post("/webhook", webhook.listener((payload) => {
     *   // for example, if your bot is offline, you should probably not handle votes and try again
     *   if (bot.offline) {
     *     throw new Error("Bot offline");
     *   }
     * }));
     * ```
     *
     * @param fn Vote handling function, this function can also throw an error to
     *   allow for the webhook to resend from Top.gg
     * @returns An express request handler
     */
    listener(fn) {
        return async (req, res, next) => {
            const response = await this._parseRequest(req, res);
            if (!response)
                return;
            try {
                await fn(response, req, res, next);
            }
            catch (err) {
                if (err instanceof Error)
                    this.options.error?.(err);
                res.sendStatus(500);
            }
        };
    }
}
